\begin{abstract}
We study the tightness of a master inequality bounding the achievable speed-up
of an ordered search (``scan'') policy over a discrete window, in terms of two
shape parameters of the positional prior: the forward/backward cost ratio
$\Lambda$ and the alignment ratio $\Theta$. The inequality reads
$S \le 1/(\Lambda\Theta\hat q)$ with $\hat q$ a coverage parameter.
Our starting point is a conservation identity: for any probability profile on
$M$ cells, the ascending and descending expected probe counts satisfy
$\casc + \cdesc = M+1 = 2C_0$, where $C_0 = (M+1)/2$ is the flat-profile
baseline. This collapses the parameter pair $(\Lambda,\Theta)$ to a single
degree of freedom and yields the exact identities
$X := C_0/\casc = 1/\Theta = (1+\Lambda)/(2\Lambda)$ and
$1/(\Lambda\Theta) = X\cdot(1/\Lambda)$, so the gap between the bound and the
best realizable speed-up is exactly the scalar $X$, independent of the policy
and of the baseline of the speed-up. We prove: optimality and uniqueness of the
ascending scan on front-loaded priors; strict unattainability of the bound,
$X>1$, for every front-loaded non-flat prior, with equality exactly at
$\casc=C_0$; sharpness of the bound over the class of priors; an optimal $L^1$
dispersion strengthening $S(1+\|p-\flatp\|_1/(2\casc)) \le 1/(\Lambda\Theta)$;
a mean-position fibration with exact reachable range
$X\in[(M+1)/(2M),(M+1)/2]$ and its exact constrained analogue under a tail-mass
constraint; strict monotonicity of the slack under grid refinement, so finite
grids under-estimate it; profile-forcing of slack for the harmonic law on every
window ratio; and non-identifiability of the coverage parameter, which voids
the historical anchor evidence for tightness. On the measured profile
($\Lambda = 0.765671$) one gets $\Theta\approx0.867$,
$X\approx1.15302\in[1.102,1.221]$, best realizable speed-up $\approx1.306$,
bound $\approx1.506$: the bound overshoots every realizable policy by
$10\%$--$22\%$, and the overshoot is profile-forced and policy-independent.
\end{abstract}

\section{Introduction}

\subsection{The problem}

An ordered search over a window of $M$ cells is specified by a permutation of
the cells: the \emph{policy}. If the target's position is random with a known
prior, the expected number of probes depends on the policy, and a policy
aligned with the prior does better than one anti-aligned with it. The natural
summary of ``how much better'' is a \emph{speed-up} $S$: the ratio of the cost
of a reference policy to the cost of the chosen policy.

A master inequality bounds this speed-up in terms of two shape parameters of
the prior together with a coverage parameter:
\[
S \;\le\; \min\!\left(\frac{1}{\Lambda\Theta\hat q},\ \frac{2^{k}}{\Lambda\Theta}\right),
\]
where $k$ counts bits of side information available to the policy. In the
\emph{test-blind} regime $k=0$ and for $\hat q\le1$ the first arm binds, and
when the whole window is scanned $\hat q=1$, so
\begin{equation}\label{eq:master}
S \;\le\; \frac{1}{\Lambda\Theta}.
\end{equation}
This inequality is a theorem. The question addressed here is different:
\emph{can it be attained?}

\subsection{Contributions}

We show the answer is determined by a single scalar; that this scalar exceeds
one for every front-loaded non-flat prior; that its value is fixed entirely by
the first moment of the prior; and that a logical trap has historically
corrupted assessments of tightness. The bound is not weakened by these results.
It is \emph{located}: exactly right as a statement about a class of priors, and
exactly wrong as a statement about any individual non-degenerate pool.

\subsection{Notation}

$M\ge1$ is the number of cells, indexed $i\in\{0,\dots,M-1\}$. A \emph{profile}
is $p$ with $p_i\ge0$ and $\sum_i p_i = 1$. A profile is \emph{front-loaded} if
it is non-increasing, \emph{flat} if $p_i=1/M$ for all $i$, and
\emph{non-flat} if $p_{i_0}\ne p_{j_0}$ for some pair. A \emph{policy} is a
permutation $\sigma$; it probes cell $i$ at rank $\sigma(i)+1$.

\section{Costs, parameters, and the conservation identity}

\begin{definition}[Costs]
For a profile $p$ on $M$ cells,
\[
\casc(p) = \sum_i (i+1)p_i,\quad
\cdesc(p) = \sum_i (M-i)p_i,\quad
C_0(M) = \frac{M+1}{2},\quad
c(p,\sigma) = \sum_i (\sigma(i)+1)p_i.
\]
\end{definition}

$C_0$ is simultaneously the cost of every policy under the flat profile and the
expected cost of a uniformly random policy under any profile.

\begin{definition}[Shape parameters, speed-ups, slack]
\[
\Lambda(p) = \frac{\casc(p)}{\cdesc(p)},\quad
\Theta(p) = \frac{\casc(p)}{C_0(M)},\quad
X(p) = \frac{C_0(M)}{\casc(p)},
\]
\[
S(p,\sigma) = \frac{\cdesc(p)}{c(p,\sigma)},\qquad
\Sasc(p) = \frac{\cdesc(p)}{\casc(p)} = \frac{1}{\Lambda(p)}.
\]
$X$ is the \emph{slack factor}, and $B(\Lambda,\Theta,q) = 1/(\Lambda\Theta q)$
denotes the right-hand side of \eqref{eq:master}.
\end{definition}

\begin{proposition}[Positivity]\label{prop:pos}
For any profile, $\casc \ge 1$ and $\cdesc \ge 1$; hence $\Lambda,\Theta,X$ are
strictly positive and finite.
\end{proposition}

\begin{proof}
Each rank weight satisfies $i+1\ge1$ and $M-i\ge1$ (as $i\le M-1$); weight by
$p_i\ge0$ and sum, using $\sum_i p_i = 1$.
\end{proof}

\begin{theorem}[Conservation identity]\label{thm:cons}
For every profile $p$ on $M$ cells,
\[
\casc(p) + \cdesc(p) \;=\; M+1 \;=\; 2\,C_0(M).
\]
\end{theorem}

\begin{proof}
Termwise $(i+1)+(M-i) = M+1$, independently of $i$; hence the sum is
$(M+1)\sum_i p_i = M+1$.
\end{proof}

This is the engine of the paper: the pair $(\casc,\cdesc)$ lives on a line, so
the apparently two-dimensional parameter space $(\Lambda,\Theta)$ is a curve.

\section{The identity chain}

\begin{theorem}[Identity chain]\label{thm:chain}
For every profile $p$ on $M\ge1$ cells,
\[
\text{(i)}\ X=\frac1\Theta;\qquad
\text{(ii)}\ X=\frac{1+\Lambda}{2\Lambda};\qquad
\text{(iii)}\ \Theta=\frac{2\Lambda}{1+\Lambda};\qquad
\text{(iv)}\ B(\Lambda,\Theta,1) = X\cdot\Sasc.
\]
\end{theorem}

\begin{proof}
(i) is immediate, both sides being ratios of $C_0$ and $\casc$. For (ii),
Theorem~\ref{thm:cons} gives $C_0 = (\casc+\cdesc)/2$, so
\[
X = \frac{C_0}{\casc} = \frac{\casc+\cdesc}{2\casc}
  = \frac{\casc/\cdesc + 1}{2\,\casc/\cdesc} = \frac{1+\Lambda}{2\Lambda},
\]
dividing numerator and denominator by $\cdesc>0$. (iii) is (i) combined with
(ii). For (iv), $1/(\Lambda\Theta) = (1/\Theta)(1/\Lambda) = X\cdot\Sasc$.
\end{proof}

\begin{remark}[Policy- and baseline-independence]
Identity (iv) is the central structural statement: it factorises the bound into
the best realizable speed-up times a pure shape quantity. Since $X$ is a ratio
of two costs of $p$ alone, the overshoot is unaffected by the policy and by the
reference cost used to normalise the speed-up: replacing $\cdesc$ by any other
reference $R$ multiplies both $S$ and $B$ by $R/\cdesc$, leaving $X$ untouched.
\end{remark}

\begin{definition}[Mean probe position]
$\displaystyle \Ex(p) = \sum_i \frac{i+\tfrac12}{M}\,p_i \in (0,1).$
\end{definition}

\begin{proposition}[Mean-position form]\label{prop:mean}
For $M\ge1$, $\casc(p) = M\,\Ex(p) + \tfrac12$, and hence
\[
X(p) \;=\; \frac{M+1}{2M\,\Ex(p)+1}.
\]
\end{proposition}

\begin{proof}
$(i+1) = M\cdot\frac{i+1/2}{M}+\tfrac12$; sum against $p$ and use
$\sum_i p_i=1$. Substitute into $X = C_0/\casc$ with $C_0=(M+1)/2$.
\end{proof}

\begin{corollary}\label{cor:mono}
The map $\lambda\mapsto(1+\lambda)/(2\lambda)$ is strictly decreasing on
$(0,\infty)$, equals $1$ iff $\lambda=1$ and exceeds $1$ iff $\lambda<1$. Hence
$X>1 \iff \Lambda<1 \iff$ the ascending scan strictly beats the descending one.
\end{corollary}

\section{Optimality of the ascending scan}

\begin{theorem}[Rearrangement]\label{thm:rear}
If $p$ is front-loaded then $\casc(p)\le c(p,\sigma)$ for every policy $\sigma$.
\end{theorem}

\begin{proof}
The rank weights $a_i = i+1$ form a strictly increasing sequence and $p$ is
non-increasing, so $(p,a)$ is antivarying. The rearrangement inequality for
antivarying sequences gives $\sum_i p_i a_i \le \sum_i p_i a_{\sigma(i)}$ for
every permutation $\sigma$: pairing the largest probabilities with the smallest
ranks minimises the sum. The left side is $\casc$ and the right side is
$c(p,\sigma)$.
\end{proof}

\begin{corollary}\label{cor:best}
If $p$ is front-loaded then $S(p,\sigma)\le \Sasc(p) = 1/\Lambda(p)$ for all
$\sigma$.
\end{corollary}

\begin{theorem}[Uniqueness of the optimum]\label{thm:uniq}
If $p$ is strictly decreasing then $\casc(p) < c(p,\sigma)$ for every
$\sigma\ne\mathrm{id}$; equivalently $c(p,\sigma)=\casc(p)$ iff
$\sigma=\mathrm{id}$, and $S(p,\sigma)<\Sasc(p)$ for $\sigma\ne\mathrm{id}$.
\end{theorem}

\begin{proof}
A strictly monotone permutation of a finite totally ordered set is the identity
(its inverse is also strictly monotone, forcing $i\le\sigma(i)$ and
$\sigma(i)\le i$). So a non-identity $\sigma$ has an inversion: indices $i<j$
with $\sigma(i)>\sigma(j)$. Transposing the two ranks changes the cost by
$-(\sigma(i)-\sigma(j))(p_i-p_j)<0$ since $p_i>p_j$ strictly. Repeating removes
all inversions, strictly decreasing the cost at each step and terminating at the
identity.
\end{proof}

This rules out the objection that $\Sasc$ is one of several tied optima.

\section{Strict slack and unattainability}

\begin{lemma}[Pairwise expansion]\label{lem:pairs}
For any finite index set $I$ of size $n$ and $a,b : I\to\mathbb{R}$,
\[
\sum_{i\in I}\sum_{j\in I}(a_i-a_j)(b_i-b_j)
  = 2\Big(n\sum_i a_ib_i - \Big(\sum_i a_i\Big)\Big(\sum_i b_i\Big)\Big).
\]
\end{lemma}

\begin{proof}
Expand $(a_i-a_j)(b_i-b_j) = a_ib_i-a_ib_j-a_jb_i+a_jb_j$ and sum each term:
the first and last each contribute $n\sum a_ib_i$, the middle two each
contribute $-(\sum a)(\sum b)$.
\end{proof}

\begin{lemma}[Strict Chebyshev]\label{lem:cheb}
If $(a_i-a_j)(b_i-b_j)\le0$ for all $i,j\in I$ with strict inequality for at
least one pair, then $n\sum_i a_ib_i < (\sum_i a_i)(\sum_i b_i)$.
\end{lemma}

\begin{proof}
The double sum of Lemma~\ref{lem:pairs} is a sum of non-positive terms with at
least one strictly negative, hence strictly negative; divide by $2$ and
rearrange.
\end{proof}

\begin{theorem}[Strict slack]\label{thm:strict}
Let $p$ be front-loaded and non-flat. Then $\casc(p)<C_0(M)$, equivalently
$X(p)>1$.
\end{theorem}

\begin{proof}
Apply Lemma~\ref{lem:cheb} with $a_i=i+1$ (strictly increasing) and $b_i=p_i$
(non-increasing). For $i\le j$ we have $a_i-a_j\le0$ and $p_i-p_j\ge0$, so the
product is $\le0$, and symmetrically. If $p_{i_0}\ne p_{j_0}$ with $i_0<j_0$
then $a_{i_0}<a_{j_0}$ and $p_{i_0}>p_{j_0}$, giving a strictly negative pair.
Hence
\[
M\sum_i(i+1)p_i < \Big(\sum_i(i+1)\Big)\Big(\sum_i p_i\Big) = \frac{M(M+1)}{2},
\]
i.e.\ $\casc < (M+1)/2 = C_0$.
\end{proof}

\begin{theorem}[Equality characterisation]\label{thm:eq}
For any profile, $X(p)=1 \iff \casc(p)=C_0(M)$. In particular the flat profile
$p_i=1/M$ satisfies $X=1$.
\end{theorem}

\begin{proof}
Immediate from $X=C_0/\casc$ with $\casc>0$. For flatness,
$\sum_i (i+1)/M = \tfrac1M\cdot\tfrac{M(M+1)}2 = C_0$.
\end{proof}

\begin{theorem}[No realizable policy attains the bound]\label{thm:unattain}
Let $p$ be front-loaded and non-flat. Then for every policy $\sigma$,
\[
S(p,\sigma)\cdot X(p) \le B(\Lambda(p),\Theta(p),1)
\quad\text{and}\quad X(p)>1,
\]
hence $S(p,\sigma) < B(\Lambda(p),\Theta(p),1)$ strictly.
\end{theorem}

\begin{proof}
Corollary~\ref{cor:best} gives $S(p,\sigma)\le\Sasc$; multiply by $X>0$ and use
Theorem~\ref{thm:chain}(iv). Since $S(p,\sigma)>0$ and $X>1$ by
Theorem~\ref{thm:strict}, $S(p,\sigma) < S(p,\sigma)X \le B$.
\end{proof}

The failure of equality happens \emph{pool-side}, before any policy is chosen.
The only profiles for which \eqref{eq:master} is tight have $\casc = C_0$, and
on those there is no speed-up to be had at all: $\Lambda=1$, $\Sasc=1$,
$B=1$. Tightness and usefulness are mutually exclusive.

\section{Sharpness over the prior class}

\begin{definition}[Two-cell family]
For $0\le\delta\le\tfrac12$, let $p_\delta = (\tfrac12+\delta,\ \tfrac12-\delta)$
on $M=2$ cells.
\end{definition}

\begin{proposition}\label{prop:twocell}
$p_\delta$ is a front-loaded profile, non-flat iff $\delta>0$, with
\[
\casc(p_\delta) = \tfrac32-\delta,\qquad
X(p_\delta) = \frac{3/2}{3/2-\delta}.
\]
\end{proposition}

\begin{proof}
Nonnegativity and unit mass are immediate; monotonicity holds for $\delta\ge0$.
$\casc = 1(\tfrac12+\delta)+2(\tfrac12-\delta) = \tfrac32-\delta$ and
$C_0(2)=\tfrac32$.
\end{proof}

\begin{theorem}[Sharpness over the class]\label{thm:sharp}
For every $\varepsilon>0$ there is a front-loaded, non-flat profile $p$ with
$1<X(p)<1+\varepsilon$.
\end{theorem}

\begin{proof}
$X(p_\delta)\to1$ as $\delta\downarrow0$ by Proposition~\ref{prop:twocell}, and
$X(p_\delta)>1$ for $\delta>0$ by Theorem~\ref{thm:strict}.
\end{proof}

\begin{corollary}[The correct form of the tightness question]
No constant $c>1$ satisfies $S \le 1/(c\,\Lambda\Theta)$ uniformly over the
class of front-loaded priors; yet no admissible non-flat profile attains $X=1$.
Sharpness holds in the closure of the class; attainment holds nowhere in it.
\end{corollary}

The methodological conclusion: \emph{sharpness must be posed over the class of
priors, never as tightness on a single pool.}

\begin{theorem}[Stability / hump-insensitivity]\label{thm:stab}
For profiles $p,q$ on $M$ cells,
\[
|X(p)-X(q)| \;\le\; \frac{M+1}{2}\cdot M\sum_i|p_i-q_i|.
\]
\end{theorem}

\begin{proof}
$X(p)-X(q) = C_0(\casc(q)-\casc(p))/(\casc(p)\casc(q))$. The numerator
difference is bounded by $M\|p-q\|_1$ since every rank weight is at most $M$;
the denominator is at least $1$ by Proposition~\ref{prop:pos}.
\end{proof}

\begin{proposition}[Which arm binds]
For $\Lambda,\Theta>0$, $k=0$ and $\hat q\ge1$,
$\min(1/(\Lambda\Theta\hat q),\,2^k/(\Lambda\Theta)) = 1/(\Lambda\Theta\hat q)$.
At $\hat q=1$ the two arms coincide.
\end{proposition}

\section{A quantitative dispersion strengthening}

\begin{definition}[Flat dispersion]
$\displaystyle \|p-\flatp\|_1 = \sum_i\big|p_i-\tfrac1M\big|$, which vanishes
exactly on the flat profile.
\end{definition}

\begin{theorem}[Dispersion bound]\label{thm:disp}
For every front-loaded profile $p$,
\[
\casc(p) \le C_0(M) - \tfrac12\|p-\flatp\|_1,
\qquad
X(p) \ge 1 + \frac{\|p-\flatp\|_1}{2\casc(p)} \ge 1 + \frac{\|p-\flatp\|_1}{2M}.
\]
\end{theorem}

\begin{proof}
Return to the double sum of Lemma~\ref{lem:pairs} and keep its magnitude. For a
front-loaded profile and $a_i=i+1$, each term satisfies
$|(a_i-a_j)(p_i-p_j)| \ge |p_i-p_j|$, because $|a_i-a_j|\ge1$ for $i\ne j$.
Summing over a row $i$ and using the mass constraint gives
$\sum_j|p_i-p_j| \ge M|p_i-1/M|$ by the triangle inequality against the mean.
Summing over $i$ converts the double sum into $M\|p-\flatp\|_1$, and
Lemma~\ref{lem:pairs} turns this into $2M(C_0-\casc)\ge M\|p-\flatp\|_1$, the
first display. Dividing by $\casc$ gives the middle inequality; the last
follows from $\casc\le M$.
\end{proof}

\begin{corollary}[Refined master inequality]
For a front-loaded profile and any policy $\sigma$,
\[
S(p,\sigma)\left(1+\frac{\|p-\flatp\|_1}{2\casc(p)}\right)
  \le \frac{1}{\Lambda(p)\Theta(p)}.
\]
\end{corollary}

\begin{theorem}[Optimality of the constant]\label{thm:dispopt}
On the two-cell family, $X(p_\delta) = 1+\|p_\delta-\flatp\|_1/(2\casc(p_\delta))$
exactly for all $0\le\delta<\tfrac12$. Consequently for every $c>1$ there is an
admissible front-loaded profile with
$X(p) < 1 + c\,\|p-\flatp\|_1/(2\casc(p))$, so no constant larger than $1$ is
admissible in Theorem~\ref{thm:disp}.
\end{theorem}

\begin{proof}
$\|p_\delta-\flatp\|_1 = 2\delta$ and $\casc = \tfrac32-\delta$, so
$1+\frac{2\delta}{2(3/2-\delta)} = \frac{3/2}{3/2-\delta} = X(p_\delta)$. The
correction term is strictly positive for $\delta>0$, so multiplying it by $c>1$
strictly overshoots; $\delta = 1/4$ suffices.
\end{proof}

Thus the extremal profiles are supported on two cells, and the normalisation
$2\casc$ (strictly smaller than $2M$) is the correct one.

\section{The mean-position fibration and its polytope}

\begin{theorem}[Fibration]
Two profiles on $M$ cells with the same mean probe position have the same slack
factor; explicitly $X$ factors through $\Ex$ via Proposition~\ref{prop:mean}.
\end{theorem}

Extremality of $X$ is therefore a question about the reachable set of mean
positions, not about profile shape: all higher moments are invisible.

\begin{theorem}[Unconstrained range]\label{thm:range}
For $M\ge1$ and every profile $p$,
\[
\frac{M+1}{2M} \le X(p) \le \frac{M+1}{2},
\]
and both endpoints are attained: by the point mass on the last cell
($\Ex = \frac{2M-1}{2M}$, $X = \frac{M+1}{2M}$) and by the point mass on the
first cell ($\Ex = \frac{1}{2M}$, $X = \frac{M+1}{2}$).
\end{theorem}

\begin{proof}
$\Ex$ is a convex combination of the cell centres $\frac{i+1/2}{M}$, so it lies
in $[\frac1{2M},\frac{2M-1}{2M}]$ with endpoints attained by point masses; $X$
is strictly decreasing in $\Ex$.
\end{proof}

\begin{definition}[Edge mass]
For a cut index $K$, $\ \edge_K(p) = \sum_{i\ge K}p_i$.
\end{definition}

\begin{theorem}[Constrained bound]\label{thm:constr}
If $\edge_K(p)\ge m\ge0$ then
\[
\Ex(p) \ge \frac{\tfrac12+Km}{M},
\qquad\text{hence}\qquad
X(p) \le \frac{M+1}{2Km+2}.
\]
\end{theorem}

\begin{proof}
Split $\Ex = \sum_i\frac{i+1/2}{M}p_i$ at $K$. Below $K$ each cell centre is at
least $\frac{1/2}{M}$; at or above $K$ each is at least $\frac{K+1/2}{M}$.
Hence $\Ex \ge \frac{1/2}{M}(1-\edge_K)+\frac{K+1/2}{M}\edge_K
= \frac{1/2+K\edge_K}{M} \ge \frac{1/2+Km}{M}$. Substitute into
Proposition~\ref{prop:mean}.
\end{proof}

\begin{theorem}[Exact constrained range]\label{thm:polytope}
Let $0<K<M$ and $0\le m\le1$. Under $\edge_K(p)\ge m$ the reachable slack
factors are exactly
\[
\left[\frac{M+1}{2M},\ \frac{M+1}{2Km+2}\right],
\]
the upper endpoint attained by the two-cell profile placing mass $1-m$ on cell
$0$ and $m$ on cell $K$, and the lower endpoint by the point mass on the last
cell.
\end{theorem}

\begin{proof}
The bounds are Theorems~\ref{thm:constr} and \ref{thm:range}. The two-cell
profile $(1-m)\delta_0 + m\delta_K$ has $\edge_K = m$ exactly and
$\Ex = \frac{1/2+Km}{M}$, hence $X = \frac{M+1}{2Km+2}$; the last-cell point
mass has $\edge_K=1\ge m$ and attains the lower endpoint. Intermediate values
follow by continuity along a path of admissible profiles.
\end{proof}

So the extremal profile of the constrained linear programme is supported on at
most two cells.

\begin{corollary}[Reading the constraint backwards]
If a measurement establishes $X(p)\ge x>0$ under $\edge_K(p)\ge m$ then
$2Km+2 \le (M+1)/x$: a measured slack caps the admissible edge mass, converting
a confidence interval on $\Lambda$ into a hard constraint on the prior itself.
\end{corollary}

\section{Grid effects: refinement and the continuum}

\begin{definition}
$\displaystyle X_M(E) = \frac{M+1}{2ME+1}$, the slack of any $M$-cell profile
with mean position $E$ (Proposition~\ref{prop:mean}).
\end{definition}

\begin{theorem}[Scalar half]\label{thm:scalar}
Fix $E\in(0,\tfrac12)$. Then $X_M(E) < \frac1{2E}$ for every $M\ge1$;
$M\mapsto X_M(E)$ is strictly increasing; and $X_M(E)\to\frac1{2E}$.
\end{theorem}

\begin{proof}
$\frac{M+1}{2ME+1}<\frac1{2E} \iff 2E(M+1)<2ME+1 \iff 2E<1$. For monotonicity,
$\frac{\partial}{\partial M}\frac{M+1}{2ME+1}
= \frac{1-2E}{(2ME+1)^2}>0$. The limit follows by dividing through by $M$.
\end{proof}

\begin{definition}[Dyadic coarsening]
For a profile given by $g:\mathbb{N}\to\mathbb{R}_{\ge0}$ read on the first
$2M$ cells, its coarsening is the $M$-cell profile
$(\mathcal{C}g)_j = g_{2j}+g_{2j+1}$, with the same total mass.
\end{definition}

\begin{theorem}[Refinement raises the slack]\label{thm:refine}
With $E_{\mathrm{fine}}$ the mean position of $g$ on $2M$ cells and
$E_{\mathrm{coarse}}$ that of $\mathcal{C}g$ on $M$ cells,
\[
E_{\mathrm{coarse}} = E_{\mathrm{fine}}
  + \frac{1}{4M}\sum_{j<M}\big(g_{2j}-g_{2j+1}\big).
\]
If $g$ is pairwise front-loaded ($g_{2j}\ge g_{2j+1}$) then
$E_{\mathrm{coarse}}\ge E_{\mathrm{fine}}$; if additionally
$E_{\mathrm{fine}}<\tfrac12$ and at least one pairwise inequality is strict,
then $X(\mathcal{C}g) < X(g)$.
\end{theorem}

\begin{proof}
The coarse cell $j$ has centre $\frac{j+1/2}{M} = \frac{2j+1}{2M}$, the midpoint
of the two fine centres $\frac{2j+1/2}{2M}$ and $\frac{2j+3/2}{2M}$. Merging
therefore displaces the mass $g_{2j}$ forward by $\frac1{4M}$ and the mass
$g_{2j+1}$ backward by $\frac1{4M}$, giving the identity. Non-negativity of the
correction follows from pairwise monotonicity, and the slack comparison
combines the mean shift with Theorem~\ref{thm:scalar} applied at grid sizes $M$
and $2M$.
\end{proof}

\begin{remark}[Explicit instance]
For the four-cell profile $(0.4,0.3,0.2,0.1)$, $\Ex = 3/8$ and $X = 5/4$; its
coarsening $(0.7,0.3)$ has $X = 15/13\approx1.1538$. Refinement strictly
increases the measured slack, so the theorem is non-vacuous.
\end{remark}

Consequently every finite-grid slack estimate is a \emph{lower} bound for the
continuum slack of the same profile: a value computed on $27$ cells may be read
one-sidedly.

\section{The harmonic profile: slack is forced by the shape}

\begin{definition}
The harmonic law on the unit interval with dynamic range $r>1$ has cumulative
distribution $F_r(u) = \log(1+(r-1)u)/\log r$ on $[0,1]$ and mean position
$E(r) = \int_0^1(1-F_r(u))\,du$.
\end{definition}

\begin{theorem}[Mean position of the harmonic law]\label{thm:harmmean}
$\displaystyle E(r) = \frac{1}{\log r} - \frac{1}{r-1}.$
\end{theorem}

\begin{proof}
Substituting $v = 1+(r-1)u$,
$\int_0^1\log(1+(r-1)u)\,du = \frac{1}{r-1}\int_1^r\log v\,dv
= \frac{r\log r-(r-1)}{r-1}$. Hence
$\int_0^1 F_r = \frac{r}{r-1}-\frac{1}{\log r}$ and
$E(r) = 1-\int_0^1 F_r = \frac1{\log r}-\frac1{r-1}$.
\end{proof}

\begin{theorem}[Pad\'e inequality]\label{thm:pade}
For every $r>1$, $\ \log r > \dfrac{2(r-1)}{r+1}$.
\end{theorem}

\begin{proof}
Let $h(r) = \log r - \frac{2(r-1)}{r+1}$. Then $h(1)=0$ and
$h'(r) = \frac1r-\frac{4}{(r+1)^2} = \frac{(r-1)^2}{r(r+1)^2} > 0$ for $r>1$.
\end{proof}

\begin{corollary}\label{cor:harmhalf}
For every $r>1$, $\ 0<E(r)<\tfrac12$.
\end{corollary}

\begin{proof}
Write $L=\log r$, $d=r-1$, both positive. Then
\[
E(r)<\tfrac12 \iff \frac{d-L}{Ld}<\frac12 \iff 2(d-L)<Ld
\iff 2d < L(d+2) = L(r+1) \iff L > \frac{2(r-1)}{r+1},
\]
which is Theorem~\ref{thm:pade}. Positivity of $E$ is $L<d$, i.e.\
$\log r<r-1$ for $r>1$.
\end{proof}

\begin{theorem}[Slack is profile-forced]\label{thm:forced}
For every window ratio $r>1$ the continuum shape parameter
$\Lambda(r) = E(r)/(1-E(r))$ satisfies $\Lambda(r)<1$ and the continuum slack is
\[
X(r) = \frac{1+\Lambda(r)}{2\Lambda(r)} = \frac{1}{2E(r)} > 1.
\]
Moreover $E(r)\to0$ and hence $X(r)\to\infty$ as $r\to\infty$.
\end{theorem}

\begin{proof}
$\Lambda<1 \iff E<\tfrac12$, which is Corollary~\ref{cor:harmhalf}; the
identity $\frac{1+\Lambda}{2\Lambda} = \frac1{2E}$ follows by substituting
$\Lambda = E/(1-E)$. Finally $E(r)\sim1/\log r\to0$.
\end{proof}

No policy is mentioned in Theorem~\ref{thm:forced}: the overshoot is a property
of the measured density alone, and grows with the width of the scan window.

